#include "PacketParser.hpp"
#include "Utils.hpp"
#include <cstring>
#include <stdexcept>
static bool mac_match(const std::string& expected,const uint8_t* actual){if(expected.empty())return true;auto mac=parse_mac(expected);return std::memcmp(mac.data(),actual,6)==0;}
static bool ip_match(const std::string& expected,const uint8_t* actual){if(expected.empty())return true;uint8_t ip[4];if(!ipv4_string_to_bytes(expected,ip))throw std::runtime_error("Invalid IP: "+expected);return std::memcmp(ip,actual,4)==0;}
bool extract_udp_payload(const uint8_t* frame,size_t frame_len,const LoggerConfig& cfg,PayloadView& payload){payload={};if(frame_len<14)return false;auto eth_dst=frame;auto eth_src=frame+6;uint16_t eth_type=read_be16(frame+12);if(!mac_match(cfg.expected_dst_mac,eth_dst)||!mac_match(cfg.expected_src_mac,eth_src))return false;if(eth_type!=0x0800)return false;size_t ip_off=14;if(frame_len<ip_off+20)return false;const uint8_t* ip=frame+ip_off;uint8_t version=ip[0]>>4, ihl=ip[0]&0x0F;if(version!=4||ihl<5)return false;size_t ip_header_len=(size_t)ihl*4;if(frame_len<ip_off+ip_header_len)return false;uint16_t ip_total_len=read_be16(ip+2);if(ip_total_len<ip_header_len+8)return false;if(frame_len<ip_off+ip_total_len)return false;if(ip[9]!=17)return false;if(!ip_match(cfg.expected_src_ip,ip+12)||!ip_match(cfg.expected_dst_ip,ip+16))return false;size_t udp_off=ip_off+ip_header_len;if(frame_len<udp_off+8)return false;const uint8_t* udp=frame+udp_off;uint16_t sport=read_be16(udp), dport=read_be16(udp+2), udp_len=read_be16(udp+4);if(udp_len<8)return false;if(udp_off+udp_len>frame_len)return false;if(cfg.expected_udp_src_port!=0&&sport!=cfg.expected_udp_src_port)return false;if(cfg.expected_udp_dst_port!=0&&dport!=cfg.expected_udp_dst_port)return false;payload.data=udp+8;payload.size=udp_len-8;return true;}
